const out = [];
for (const item of items) {
  const message = item.json?.message;
  const text = message?.data?.content;
  if (message?.isSelf) continue;
  if (typeof text !== 'string' || !text.trim()) continue;

  const threadId = String(message.threadId ?? '');
  const messageId = String(message.data?.msgId ?? '');
  const messageTs = String(message.data?.ts ?? '');
  const queueKey = [threadId, messageId || messageTs].filter(Boolean).join(':');

  out.push({
    json: {
      queue_key: queueKey || `${threadId}:${Date.now()}`,
      thread_id: threadId,
      group_name: String(message.data?.dName ?? ''),
      sender_id: String(message.data?.uidFrom ?? ''),
      sender_name: String(message.data?.displayName ?? message.data?.dName ?? ''),
      message_text: text.trim(),
      message_ts: messageTs,
      raw_message_json: JSON.stringify(message),
      status: 'pending',
      retry_count: 0,
      last_error: '',
      processed_at: null,
      summary: '',
      attendance_json: '',
      needs_human_review: false,
      confidence: 0,
      appscript_response: '',
    },
  });
}
return out;
